 63→func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc, printBrowserURL bool) error {
 64→	start, err := client.StartDeviceAuth(ctx)
 65→	if err != nil {
 66→		return fmt.Errorf("start login: %w", err)
 67→	}
 68→
 69→	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
 70→	approvalURL := start.VerificationURIComplete
 71→	if approvalURL == "" {
 72→		approvalURL = start.VerificationURI
 73→	}
 74→
 75→	fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
 76→
 77→	if printBrowserURL {
 78→		fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 79→	} else {
 80→		if err := openURL(ctx, approvalURL); err != nil {
 81→			fmt.Fprintf(errW, "Warning: failed to open browser automatically: %v\n", err)
 82→			fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 83→		} else {
 84→			fmt.Fprintln(outW, "Opened your browser for approval.")
 85→		}
 86→	}
 87→
 88→	fmt.Fprintln(outW, "Waiting for approval...")
 89→
 90→	token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, start.Interval)
 91→	if err != nil {
 92→		return fmt.Errorf("complete login: %w", err)
 93→	}
 94→
 95→	store := auth.NewStore()
 96→
 97→	if err := store.SaveToken(client.BaseURL(), token); err != nil {
 98→		return fmt.Errorf("save auth token: %w", err)
 99→	}
100→
101→	fmt.Fprintln(outW, "Login complete.")
102→	return nil
103→}
