105→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
106→	expiry := time.Duration(expiresIn) * time.Second
107→	if expiry <= 0 || expiry > maxExpiresIn {
108→		expiry = maxExpiresIn
109→	}
110→	deadline := time.Now().Add(expiry)
111→	pollInterval := time.Duration(interval) * time.Second
112→	if pollInterval <= 0 {
113→		pollInterval = fallbackDeviceAuthPollInterval
114→	}
115→
116→	consecutiveErrors := 0
117→
118→	for {
119→		if time.Now().After(deadline) {
120→			return "", errors.New("device authorization expired")
121→		}
122→
123→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
124→		if err != nil {
125→			consecutiveErrors++
126→			if consecutiveErrors >= maxTransientErrors {
127→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
128→			}
129→			// Transient error — wait and retry.
130→			select {
131→			case <-ctx.Done():
132→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
133→			case <-time.After(pollInterval):
134→			}
135→			continue
136→		}
137→		consecutiveErrors = 0
138→
139→		switch result.Error {
140→		case "":
141→			if result.AccessToken == "" {
142→				return "", errors.New("device authorization completed without a token")
143→			}
144→			return result.AccessToken, nil
145→		case "authorization_pending":
146→			// no-op, will sleep and retry below
147→		case "slow_down":
148→			pollInterval += slowDownBackoff
149→			if pollInterval > maxPollInterval {
150→				pollInterval = maxPollInterval
151→			}
152→		case "access_denied":
153→			return "", errors.New("device authorization denied")
154→		case "expired_token":
155→			return "", errors.New("device authorization expired")
156→		default:
157→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
158→		}
159→
160→		select {
161→		case <-ctx.Done():
162→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
163→		case <-time.After(pollInterval):
164→		}
165→	}
166→}
