168→func openBrowser(ctx context.Context, browserURL string) error {
169→	u, err := url.Parse(browserURL)
170→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
171→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
172→	}
173→
174→	var command string
175→	var args []string
176→
177→	switch runtime.GOOS {
178→	case "darwin":
179→		command = "open"
180→		args = []string{browserURL}
181→	case "linux":
182→		command = "xdg-open"
183→		args = []string{browserURL}
184→	case "windows":
185→		command = "cmd"
186→		args = []string{"/c", "start", "", browserURL}
187→	default:
188→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
189→	}
190→
191→	cmd := exec.CommandContext(ctx, command, args...)
192→	if err := cmd.Start(); err != nil {
193→		return fmt.Errorf("start browser command %q: %w", command, err)
194→	}
195→
196→	if err := cmd.Process.Release(); err != nil {
197→		return fmt.Errorf("release browser process: %w", err)
198→	}
199→
200→	return nil
201→}
