	stdout *bufio.Reader
	waitFn func() (string, error)
}

func runLoginProcess(t *testing.T, apiBaseURL string) *loginProcess {
	t.Helper()

	env := NewTestEnv(t)

	cmd := exec.Command(getTestBinary(), "login", "--print-browser-url", "--insecure-http-auth")
	cmd.Dir = env.RepoDir
	cmd.Env = append(testutil.GitIsolatedEnv(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+env.ClaudeProjectDir,
		"ENTIRE_TEST_GEMINI_PROJECT_DIR="+env.GeminiProjectDir,
		"ENTIRE_TEST_OPENCODE_PROJECT_DIR="+env.OpenCodeProjectDir,
		"ENTIRE_TEST_TTY=0",
		"ENTIRE_API_BASE_URL="+apiBaseURL,
	)

	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		t.Fatalf("StdoutPipe() error = %v", err)
	}

	var stderr strings.Builder
	cmd.Stderr = &stderr

	if err := cmd.Start(); err != nil {
		t.Fatalf("cmd.Start() error = %v", err)
	}

	reader := bufio.NewReader(stdoutPipe)

	return &loginProcess{
		stdout: reader,
		waitFn: func() (string, error) {
			stdoutBytes, readErr := io.ReadAll(reader)
			waitErr := cmd.Wait()
			return string(stdoutBytes) + stderr.String(), errors.Join(readErr, waitErr)
		},
	}
}

