173→	u, err := url.Parse(browserURL)
174→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
175→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
176→	}
177→
178→	var command string
179→	var args []string
180→
181→	switch runtime.GOOS {
